Chapter.Code:
const float scale =
    std::exp(
        gaussian.logScale[index]);

variance[index] =
    scale * scale;

const float3 scales =
    exp(
        gaussian.logScaleRestCount.xyz);

const float3 variances =
    scales * scales;

const float3x3 worldCovariance =
    rotation *
    diag(variances) *
    transpose(rotation);

std::array<float, 4>
rotation
{
    1,0,0,0
};

